516	func proposalViewOf(round uint64, c *candidateState) ProposalView {
517		ids := append([]string(nil), c.TxIDs...)
518		return ProposalView{Round: round, BlockID: c.BlockID, TxIDs: ids, Empty: len(ids) == 0}
519	}
