1	package consensus
2	
3	import (
4		"fmt"
5		"testing"
6	)
7	
8	// setupTwoTxNode 准备一个含两笔交易的新节点：tx1（keys[0]，费用 1）、
9	// tx2（keys[1]，费用 2）。本地提议按费用打包，顺序固定为 [tx2, tx1]。
10	func setupTwoTxNode(t *testing.T) (*Node, string, []testKey, *Transaction, *Transaction) {
11		t.Helper()
12		keys := genKeys(t, 4)
13		n, dir := newTestNode(t, keys, 10)
14		tx1 := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 100)
15		tx2 := NewTransaction(keys[1].priv, 1, []byte("b"), 2, 100)
16		if _, err := n.Submit(tx1); err != nil {
17			t.Fatal(err)
18		}
19		if _, err := n.Submit(tx2); err != nil {
20			t.Fatal(err)
21		}
22		return n, dir, keys, tx1, tx2
23	}
24	
25	// assertBlock 校验确认块的交易列表、高度、轮次、区块标识与前块标识。
26	func assertBlock(t *testing.T, b Block, wantTx []string, height, round uint64, id, prev string) {
27		t.Helper()
28		if fmt.Sprint(b.TxIDs) != fmt.Sprint(wantTx) {
29			t.Fatalf("block tx ids = %v, want %v", b.TxIDs, wantTx)
30		}
31		if b.Height != height || b.Round != round || b.ID != id || b.PreviousID != prev {
32			t.Fatalf("block header = {h:%d r:%d id:%s prev:%s}, want {h:%d r:%d id:%s prev:%s}",
33				b.Height, b.Round, b.ID, b.PreviousID, height, round, id, prev)
34		}
35	}
36	
37	// tamperBlock 以调用方身份尽力改写手中的确认块：交换顺序、改标识、追加长度。
38	func tamperBlock(b *Block) {
39		if len(b.TxIDs) >= 2 {
40			b.TxIDs[0], b.TxIDs[1] = b.TxIDs[1], b.TxIDs[0]
41		}
42		b.TxIDs[0] = "tampered-id"
43		b.TxIDs = append(b.TxIDs, "appended-id")
44	}
45	
46	// Vote 确认时返回的确认块是独立快照：交换、改写、追加只影响调用方手中的结果；
47	// 随后 BlockAt/LatestBlock 仍是实际胜出候选的原始列表与顺序，
48	// 高度、轮次、区块标识及前块标识保持原值；交易查询与候选历史同样不受影响。
49	func TestVoteConfirmedBlockIsSnapshot(t *testing.T) {
50		n, _, keys, tx1, tx2 := setupTwoTxNode(t)
51		p, _ := n.Propose()
52		want := []string{tx2.ID(), tx1.ID()}
53		if fmt.Sprint(p.TxIDs) != fmt.Sprint(want) {
54			t.Fatalf("setup order = %v, want %v", p.TxIDs, want)
55		}
56	
57		var confirmed *VoteResult
58		for i := 0; i < 3; i++ {
59			res, err := n.Vote(keys[i].pub, 1, p.BlockID)
60			if err != nil {
61				t.Fatal(err)
62			}
63			if i < 2 {
64				// 尚未达到确认条件时不返回确认块。
65				if res.Confirmed || res.Block != nil {
66					t.Fatalf("vote %d must not return a block: %+v", i+1, res)
67				}
68			} else {
69				if !res.Confirmed || res.Block == nil {
70					t.Fatalf("third vote should confirm: %+v", res)
71				}
72				confirmed = res
73			}
74		}
75		assertBlock(t, *confirmed.Block, want, 1, 1, p.BlockID, "")
76	
77		// 调用方尽力改写 Vote 返回结果。
78		tamperBlock(confirmed.Block)
79	
80		got, err := n.BlockAt(1)
81		if err != nil {
82			t.Fatal(err)
83		}
84		assertBlock(t, got, want, 1, 1, p.BlockID, "")
85		latest, ok := n.LatestBlock()
86		if !ok {
87			t.Fatal("latest block should exist")
88		}
89		assertBlock(t, latest, want, 1, 1, p.BlockID, "")
90	
91		// 区块标识与交易查询仍指向原来的确认结果。
92		for _, tx := range []*Transaction{tx1, tx2} {
93			info, err := n.Tx(tx.ID())
94			if err != nil {
95				t.Fatal(err)
96			}
97			if info.Status != StatusConfirmed || info.BlockHeight != 1 || info.BlockID != p.BlockID {
98				t.Fatalf("tx %s lookup wrong: %+v", tx.ID(), info)
99			}
100		}
101	
102		// 候选历史中的胜出交易列表与确认块一致。
103		rc, err := n.Candidates(1)
104		if err != nil {
105			t.Fatal(err)
106		}
107		var winner *CandidateView
108		for i := range rc.Candidates {
109			if rc.Candidates[i].Result == CandidateWon {
110				winner = &rc.Candidates[i]
111			}
112		}
113		if winner == nil || winner.BlockID != p.BlockID || fmt.Sprint(winner.TxIDs) != fmt.Sprint(want) {
114			t.Fatalf("winner candidate history wrong: %+v", winner)
115		}
116	}
117	
118	// 同一高度的多份返回结果互不影响：改一份，其他已取得结果保持原样；
119	// Vote 确认块与查询取得的区块之间也互不别名。
120	func TestMultipleBlockSnapshotsIndependent(t *testing.T) {
121		n, _, keys, tx1, tx2 := setupTwoTxNode(t)
122		p, _ := n.Propose()
123		want := []string{tx2.ID(), tx1.ID()}
124		confirmByVotes(t, n, keys, p.BlockID)
125	
126		b1, err := n.BlockAt(1)
127		if err != nil {
128			t.Fatal(err)
129		}
130		b2, err := n.BlockAt(1)
131		if err != nil {
132			t.Fatal(err)
133		}
134		latest, ok := n.LatestBlock()
135		if !ok {
136			t.Fatal("latest block should exist")
137		}
138	
139		// 改写先取得的一份，其余已取得的结果保持原样。
140		tamperBlock(&b1)
141		assertBlock(t, b2, want, 1, 1, p.BlockID, "")
142		assertBlock(t, latest, want, 1, 1, p.BlockID, "")
143	
144		// 再改写 LatestBlock 结果，BlockAt 结果与新查询仍保持原样。
145		tamperBlock(&latest)
146		assertBlock(t, b2, want, 1, 1, p.BlockID, "")
147		b3, _ := n.BlockAt(1)
148		assertBlock(t, b3, want, 1, 1, p.BlockID, "")
149	}
150	
151	// 本地修改不会随正常操作进入持久化历史：把返回列表第一笔改成不存在的标识、
152	// 追加标识后，合法提交一笔新交易使节点保存状态；停止重开同一状态目录，
153	// 原确认块仍保留真正确认的交易及其顺序与区块标识，篡改标识不作为交易存在。
154	func TestBlockSnapshotMutationNeverPersisted(t *testing.T) {
155		n, dir, keys, tx1, tx2 := setupTwoTxNode(t)
156		p, _ := n.Propose()
157		want := []string{tx2.ID(), tx1.ID()}
158		res := confirmByVotesResult(t, n, keys, p.BlockID)
159	
160		// 同时篡改 Vote 返回块与 BlockAt 返回块。
161		tamperBlock(res.Block)
162		got, _ := n.BlockAt(1)
163		got.TxIDs[0] = "nonexistent-id"
164		got.TxIDs = append(got.TxIDs, "phantom-id")
165	
166		// 合法提交一笔新交易，触发正常保存。
167		tx3 := NewTransaction(keys[0].priv, 2, []byte("c"), 1, 100)
168		if _, err := n.Submit(tx3); err != nil {
169			t.Fatalf("legitimate submit after tamper failed: %v", err)
170		}
171	
172		// 停止后重新打开同一状态目录，历史保持真正确认的结果。
173		reopened, err := Open(dir)
174		if err != nil {
175			t.Fatal(err)
176		}
177		if reopened.Height() != 1 || reopened.CurrentRound() != 2 {
178			t.Fatalf("reopened state wrong: height=%d round=%d", reopened.Height(), reopened.CurrentRound())
179		}
180		stored, err := reopened.BlockAt(1)
181		if err != nil {
182			t.Fatal(err)
183		}
184		assertBlock(t, stored, want, 1, 1, p.BlockID, "")
185		storedLatest, ok := reopened.LatestBlock()
186		if !ok {
187			t.Fatal("latest block should exist after reopen")
188		}
189		assertBlock(t, storedLatest, want, 1, 1, p.BlockID, "")
190	
191		// 原交易查询仍显示原确认高度与区块标识。
192		for _, tx := range []*Transaction{tx1, tx2} {
193			info, err := reopened.Tx(tx.ID())
194			if err != nil {
195				t.Fatal(err)
196			}
197			if info.Status != StatusConfirmed || info.BlockHeight != 1 || info.BlockID != p.BlockID {
198				t.Fatalf("tx %s lookup after reopen wrong: %+v", tx.ID(), info)
199			}
200		}
201		// 篡改出来的标识没有进入历史。
202		if _, err := reopened.Tx("nonexistent-id"); reason(err) != ReasonUnknownTx {
203			t.Fatalf("tampered id persisted as transaction: %v", err)
204		}
205		// 新交易正常待处理，账户确认序号仍为真实历史推进的结果。
206		info, err := reopened.Tx(tx3.ID())
207		if err != nil || info.Status != StatusQueued {
208			t.Fatalf("new tx after reopen wrong: %+v %v", info, err)
209		}
210		// 候选历史中的胜出列表与确认块一致。
211		rc, err := reopened.Candidates(1)
212		if err != nil {
213			t.Fatal(err)
214		}
215		for _, c := range rc.Candidates {
216			if c.Result == CandidateWon && (c.BlockID != p.BlockID || fmt.Sprint(c.TxIDs) != fmt.Sprint(want)) {
217				t.Fatalf("winner history inconsistent after reopen: %+v", c)
218			}
219		}
220	}
