222	// 胜出者是竞争候选时，确认块返回结果同样遵守快照规则，且篡改不会落盘。
223	func TestCompetingWinnerBlockIsSnapshotAndNotPersisted(t *testing.T) {
224		n, dir, keys, tx1, tx2 := setupTwoTxNode(t)
225		local, _ := n.Propose() // 本地提议顺序 [tx2, tx1]。
226		// 竞争候选以相反顺序登记并胜出。
227		altWant := []string{tx1.ID(), tx2.ID()}
228		alt, err := n.RegisterCandidate(1, altWant)
229		if err != nil {
230			t.Fatal(err)
231		}
232		res := confirmByVotesResult(t, n, keys, alt.BlockID)
233		assertBlock(t, *res.Block, altWant, 1, 1, alt.BlockID, "")
234	
235		// 篡改 Vote 返回块：顺序与列表长度都被改变。
236		tamperBlock(res.Block)
237		got, _ := n.BlockAt(1)
238		assertBlock(t, got, altWant, 1, 1, alt.BlockID, "")
239	
240		// 候选历史：竞争候选胜出且列表与确认块一致，本地提议落选。
241		rc, _ := n.Candidates(1)
242		for _, c := range rc.Candidates {
243			switch c.BlockID {
244			case alt.BlockID:
245				if c.Result != CandidateWon || fmt.Sprint(c.TxIDs) != fmt.Sprint(altWant) {
246					t.Fatalf("competing winner history wrong: %+v", c)
247				}
248			case local.BlockID:
249				if c.Result != CandidateLost {
250					t.Fatalf("local candidate should be lost: %+v", c)
251				}
252			}
253		}
254	
255		// 触发一次正常保存后重开，竞争候选的原始胜出结果保持不变。
256		tx3 := NewTransaction(keys[0].priv, 2, []byte("c"), 1, 100)
257		if _, err := n.Submit(tx3); err != nil {
258			t.Fatal(err)
259		}
260		reopened, err := Open(dir)
261		if err != nil {
262			t.Fatal(err)
263		}
264		stored, _ := reopened.BlockAt(1)
265		assertBlock(t, stored, altWant, 1, 1, alt.BlockID, "")
266		for _, tx := range []*Transaction{tx1, tx2} {
267			info, err := reopened.Tx(tx.ID())
268			if err != nil {
269				t.Fatal(err)
270			}
271			if info.Status != StatusConfirmed || info.BlockHeight != 1 || info.BlockID != alt.BlockID {
272				t.Fatalf("competing-winner tx %s wrong after reopen: %+v", tx.ID(), info)
273			}
274		}
275	}
276	
277	// 空确认块仍返回零笔交易：给返回列表追加标识不能使节点历史多出交易，
278	// 也不会在后续保存后落盘。
279	func TestEmptyBlockSnapshotStaysEmpty(t *testing.T) {
280		keys := genKeys(t, 4)
281		n, dir := newTestNode(t, keys, 10)
282		p, err := n.Propose()
283		if err != nil {
284			t.Fatal(err)
285		}
286		if !p.Empty {
287			t.Fatal("setup: want empty proposal")
288		}
289		res := confirmByVotesResult(t, n, keys, p.BlockID)
290		if len(res.Block.TxIDs) != 0 {
291			t.Fatalf("empty block must return zero txs, got %v", res.Block.TxIDs)
292		}
293	
294		// 调用方向 Vote 返回块追加标识。
295		res.Block.TxIDs = append(res.Block.TxIDs, "phantom-from-vote")
296		if got, _ := n.BlockAt(1); len(got.TxIDs) != 0 {
297			t.Fatalf("vote append leaked into history: %v", got.TxIDs)
298		}
299		// 调用方向 LatestBlock 返回块追加标识。
300		latest, ok := n.LatestBlock()
301		if !ok {
302			t.Fatal("empty block should exist")
303		}
304		latest.TxIDs = append(latest.TxIDs, "phantom-from-latest")
305		if got, _ := n.BlockAt(1); len(got.TxIDs) != 0 {
306			t.Fatalf("latest append leaked into history: %v", got.TxIDs)
307		}
308	
309		// 进入下一轮并触发正常保存，重开后历史仍是零笔交易的空块。
310		if _, err := n.Propose(); err != nil {
311			t.Fatal(err)
312		}
313		reopened, err := Open(dir)
314		if err != nil {
315			t.Fatal(err)
316		}
317		if reopened.Height() != 1 {
318			t.Fatalf("height = %d, want 1", reopened.Height())
319		}
320		stored, err := reopened.BlockAt(1)
321		if err != nil {
322			t.Fatal(err)
323		}
324		if len(stored.TxIDs) != 0 || stored.ID != p.BlockID || stored.Height != 1 || stored.Round != 1 {
325			t.Fatalf("empty block changed after reopen: %+v", stored)
326		}
327		storedLatest, ok := reopened.LatestBlock()
328		if !ok || len(storedLatest.TxIDs) != 0 || storedLatest.ID != p.BlockID {
329			t.Fatalf("latest empty block wrong after reopen: %+v ok=%v", storedLatest, ok)
330		}
331	}
332	
333	// 边界行为保持兼容：尚无确认块时 LatestBlock 不存在；高度 0 或超过最新高度
334	// 的 BlockAt 以 unknown-block 拒绝。
335	func TestBlockQueryBoundariesUnchanged(t *testing.T) {
336		keys := genKeys(t, 4)
337		n, _ := newTestNode(t, keys, 10)
338	
339		if _, ok := n.LatestBlock(); ok {
340			t.Fatal("LatestBlock must report absent before any confirmation")
341		}
342		if _, err := n.BlockAt(0); reason(err) != ReasonUnknownBlock {
343			t.Fatalf("height 0 got %v, want %s", err, ReasonUnknownBlock)
344		}
345		if _, err := n.BlockAt(1); reason(err) != ReasonUnknownBlock {
346			t.Fatalf("height beyond tip got %v, want %s", err, ReasonUnknownBlock)
347		}
348	
349		p, _ := n.Propose()
350		// 未确认前按高度仍查不到块。
351		if _, err := n.BlockAt(1); reason(err) != ReasonUnknownBlock {
352			t.Fatalf("unconfirmed height got %v, want %s", err, ReasonUnknownBlock)
353		}
354		confirmByVotes(t, n, keys, p.BlockID)
355		if _, err := n.BlockAt(0); reason(err) != ReasonUnknownBlock {
356			t.Fatalf("height 0 after confirm got %v, want %s", err, ReasonUnknownBlock)
357		}
358		if _, err := n.BlockAt(2); reason(err) != ReasonUnknownBlock {
359			t.Fatalf("height beyond tip after confirm got %v, want %s", err, ReasonUnknownBlock)
360		}
361		if latest, ok := n.LatestBlock(); !ok || latest.ID != p.BlockID || latest.Height != 1 {
362			t.Fatalf("latest after confirm wrong: %+v ok=%v", latest, ok)
363		}
364	}
365	
366	// confirmByVotesResult 投票至确认并返回决定性那次的结果（含确认块）。
367	func confirmByVotesResult(t *testing.T, n *Node, keys []testKey, blockID string) *VoteResult {
368		t.Helper()
369		round := n.CurrentRound()
370		count := len(keys)*2/3 + 1
371		var last *VoteResult
372		for i := 0; i < count; i++ {
373			res, err := n.Vote(keys[i].pub, round, blockID)
374			if err != nil {
375				t.Fatalf("vote %d: %v", i, err)
376			}
377			last = res
378		}
379		if !last.Confirmed || last.Block == nil {
380			t.Fatalf("block %s was not confirmed", blockID)
381		}
382		return last
383	}
